import * as React from "react"

function MarkertShop({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="markert-shop"
      className={className}
      {...props}
    >
      <style>{"body {
      margin: 0;
      font-family: 'Segoe UI', sans-serif;
      background-color: #f7f7f7;
      color: #333;
    }
    header {
      background: #0a66c2;
      color: white;
      padding: 60px 20px;
      text-align: center;
    }
    header h1 {
      font-size: 3em;
      margin: 0;
    }
    header p {
      font-size: 1.2em;
      margin-top: 10px;
    }
    .features {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      padding: 40px 20px;
      background: white;
    }
    .feature {
      flex: 1 1 300px;
      max-width: 300px;
      background: #e9f3ff;
      margin: 10px;
      padding: 20px;
      border-radius: 10px;
    }
    .feature h3 {
      margin-top: 0;
      color: #0a66c2;
    }
    .subscribe {
      background: #d9edff;
      padding: 40px 20px;
      text-align: center;
    }
    .subscribe input {
      padding: 10px;
      width: 250px;
      max-width: 80%;
      margin-right: 10px;
      border: 1px solid #ccc;
      border-radius: 5px;
    }
    .subscribe button {
      padding: 10px 20px;
      background: #0a66c2;
      color: white;
      border: none;
      border-radius: 5px;
      cursor: pointer;
    }
    .subscribe button:hover {
      background: #084a96;
    }
    footer {
      text-align: center;
      padding: 20px;
      background: #333;
      color: white;
    }"}</style>
      <header>
          <h1>Boost Your Business Online</h1>
          <p>Reach thousands of customers with powerful digital marketing tools</p>
        </header>

        <section className="features">
          <div className="feature">
            <h3>SEO Optimization</h3>
            <p>Get found on Google and improve your search engine rankings.</p>
          </div>
          <div className="feature">
            <h3>Social Media Ads</h3>
            <p>Target the right audience with optimized Facebook and Instagram ads.</p>
          </div>
          <div className="feature">
            <h3>Email Campaigns</h3>
            <p>Send professional emails that convert leads into loyal customers.</p>
          </div>
        </section>

        <section className="subscribe">
          <h2>Join Our Newsletter</h2>
          <p>Stay updated with the latest tips & offers</p>
          <form id="subscribeForm">
            <input type="email" id="email" placeholder="Enter your email" required />
            <button type="submit">Subscribe</button>
          </form>
        </section>

        <footer>
          &copy; 2025 Online Marketing Co. All rights reserved.
        </footer>
    </div>
  )
}

export { MarkertShop }
